trait RecordWords {
  def record[A1, P](f1: Shape.Field[A1])(make: A1 => P)(unmake: P => A1): Shape[P] =
    Shape.Record[P](FreeAp.Ap(FreeAp.pure[Shape.Field, A1 => P](make), f1.free),
      (p: P) => Vector(f1.name -> f1.shape.encode(unmake(p))))
